// Attachment Общая схема, представляющая вложение сообщения
type Attachment struct {
	union json.RawMessage
}

// AttachmentPayload Базовая полезная нагрузка медиа-вложения
type AttachmentPayload struct {
	// Url URL медиа-вложения. Этот URL будет получен в объекте Update после
	// отправки сообщения в чат.
	//
	// Прямую ссылку на видео также можно получить с помощью метода
	// `GET /videos/{-videoToken-}`. 2048 — официальный лимит URL в оригинальной
	// схеме (LinkButton.url, LinkMarkup.url)
	Url string `json:"url"`
}

// AttachmentRequest Запрос на прикрепление данных к сообщению
type AttachmentRequest struct {
	union json.RawMessage
}

// AudioAttachment Вложение аудио
type AudioAttachment struct {
	// Payload Полезная нагрузка аудио-вложения
	Payload MediaAttachmentPayload `json:"payload"`

	// Transcription Аудио транскрипция. 255 — в оригинале лимита нет; временный лимит, пока
	// транскрипции не используются
	Transcription *string `json:"transcription,omitempty"`

	// Type Тип вложения: `audio`
	Type AudioAttachmentType `json:"type"`
}

// AudioAttachmentType Тип вложения: `audio`
type AudioAttachmentType string

// AudioAttachmentRequest Запрос на прикрепление аудио к сообщению. Должен быть единственным вложением в сообщении
type AudioAttachmentRequest struct {
	// Payload Полезная нагрузка запроса на прикрепление аудио
	Payload UploadedInfo `json:"payload"`

	// Type Тип вложения: `audio`
	Type AudioAttachmentRequestType `json:"type"`
}

// AudioAttachmentRequestType Тип вложения: `audio`
type AudioAttachmentRequestType string

